protected void buildTransferSettingsDialogGroup()
{
    next buildTransferSettingsDialogGroup();

    if (copyDeliveryAddressToLines != CopyDeliveryAddressFromHeaderToLine::DontTransfer)
    {
        // Create Address Prompt
        copyDeliveryAddressToLinesField.value(CopyDeliveryAddressFromHeaderToLine::TransferToAllLines);
        fieldList.insert(fieldNum(SalesTable, DeliveryPostalAddress), copyDeliveryAddressToLinesField);
    }
}
